export function getStackSubstanceLabel(id: string): string {
  if (!id) return '—';
  if (L[id]) return L[id]
  const catEntry = SUPPORT_CATALOG_DATA[id];
  if (catEntry) return catEntry.nameRu || catEntry.name;
  return id.replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase());
}

